CREATE TABLE rooms (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  name text NOT NULL,
  capacity integer NOT NULL
);

INSERT INTO rooms (name, capacity)
VALUES ('Turing', 6), ('Lovelace', 4), ('Hopper', 8);

SELECT id, name, capacity
FROM rooms
WHERE capacity >= 5
ORDER BY capacity DESC;

UPDATE rooms SET capacity = 5 WHERE name = 'Lovelace';

DELETE FROM rooms WHERE id = 3;

SELECT * FROM rooms ORDER BY id;

INSERT INTO rooms (name) VALUES ('Knuth');

SELECT '2026-10-05 15:00:00+01'::timestamptz AS starts_at;

SET TIME ZONE 'America/New_York';

SELECT '2026-10-05 14:00:00Z'::timestamptz AS starts_at;

SELECT name, amenities
FROM rooms
WHERE 'screen' = ANY (amenities);
